<?php declare(strict_types=1);

use PHPUnit\Framework\TestCase;

require_once __DIR__ . '/../../lib/logger.php';
require_once __DIR__ . '/../../ext/relationship_dynamics/relationship_dynamics.php';
require_once __DIR__ . '/../../ext/relationship_dynamics/tools/trait_equivalence_capture.php';

/**
 * Personality traits phase 1 (D:\docs\reldyn-personality-traits-design.md §6.1-6.2): the engine
 * swap changes no behaviour. Every temperament-keyed consumer, for each of the 13 presets and
 * the no-temperament / fallback labels (null, '', lower-case 'stoic', the non-temperament MDD
 * 15.4 row 'Volatile'), must read today's value through the trait engine (1e-9, same PHP type).
 *
 * BASE_FIXTURE was captured from base 33392df6 (the code before the engine), not typed:
 *   git archive 33392df6 ext/relationship_dynamics lib | tar -x -C /tmp/rd_base
 *   php ext/relationship_dynamics/tools/trait_equivalence_capture.php /tmp/rd_base
 * The test runs the same capture (tools/trait_equivalence_capture.php) against this tree.
 *
 * Phase 3 (design §6.1 item 3) changes behaviour on purpose, one fix per commit. Each fix lists
 * the capture paths it changes in DELIBERATE (fnmatch patterns over "label/consumer/..."); those
 * paths are asserted by the fix's own test (RelDynTraitPhase3Test), everything else must still be
 * today's value, and every pattern must match at least one path that really changed.
 */
final class RelDynTraitEquivalenceTest extends TestCase
{
    private const PRESETS = ['Romantic', 'Anxious', 'Bold', 'Playful', 'Humble', 'Nurturing', 'Gentle',
        'Jealous', 'Proud', 'Defiant', 'Guarded', 'Independent', 'Stoic'];

    /** Phase-3 deliberate changes: fix => capture-path patterns it changes (see the class doc). */
    private const DELIBERATE = [
        // MDD 15.4 edits (decisions §16 #6): R maturity retired, the Volatile row deleted
        'mdd_15_4_edits' => ['*/resistance/maturity', 'Volatile/resistance/*'],
        // Attachment de-duplication (design §2.2): the Anxious anxiety residuals of A3 / A4 / A15h
        // up and A18 absence decay are gone (the attachment carries them: a derived anxiety now
        // lifts the reunion), A18 is owned by possessiveness, A20 codependence reads possessiveness
        'attachment_dedup' => ['Anxious/reunion_mult', 'Anxious/jealousy_mult', 'Anxious/plasticity/trust/Y_up',
            'Anxious/apply_delta/trust/*', 'Anxious/physical/injured/injured/trust', '*/e2e/reunion',
            'Anxious/e2e/jealousy/*', 'Anxious/absence_decay', '*/neglect/*',
            'Anxious/column/reunion_mult', 'Anxious/column/jealousy_mult', 'Anxious/column/y_trust_up', 'Anxious/column/absence_decay'],
        // Bleedout redesign (design §2.5): the fall is fight C Pd (1 - D) - fear L (1 - C) at every
        // preset (the old drain table is retired); no vector keeps -1.5
        'bleedout_redesign' => ['*/bleedout'],
    ];

    /** Paths that differ from the base fixture, filled by the consumer / column comparisons. */
    private array $changed = [];

    private static function deliberate(string $path): ?string
    {
        foreach (self::DELIBERATE as $fix => $patterns) {
            foreach ($patterns as $pat) {
                if (fnmatch($pat, $path, FNM_NOESCAPE)) return $fix;
            }
        }
        return null;
    }

    private $savedDb;
    private $savedRequest;
    private static ?array $base = null;
    private static ?array $now = null;

    protected function setUp(): void
    {
        // Personality traits phase 2: this class pins the LABEL assignment (the phase-1 legacy path):
        // its NPCs' temperaments are the old core-data vote's. The read assignment has its own tests.
        RelDynTraits::$assignmentOverride = 'label';
        $this->savedDb = $GLOBALS['db'] ?? null;
        $this->savedRequest = $GLOBALS['gameRequest'] ?? null;
        unset($GLOBALS['db']);   // no stored config: shipped defaults, as the fixture was captured
        RelationshipDynamics::clearConfigCache();
    }

    protected function tearDown(): void
    {
        RelDynTraits::$assignmentOverride = null;
        if ($this->savedDb !== null) $GLOBALS['db'] = $this->savedDb;
        if ($this->savedRequest !== null) $GLOBALS['gameRequest'] = $this->savedRequest; else unset($GLOBALS['gameRequest']);
        RelationshipDynamics::clearConfigCache();
    }

    private static function base(): array
    {
        return self::$base ??= json_decode(self::BASE_FIXTURE, true, 512, JSON_THROW_ON_ERROR);
    }

    private static function now(): array
    {
        if (self::$now === null) {
            $log = ini_get('error_log');
            ini_set('error_log', '/dev/null');   // the consumers log what they do; the values are the point
            try {
                self::$now = json_decode(reldyn_trait_capture_json(reldyn_trait_capture_all()), true, 512, JSON_THROW_ON_ERROR);
            } finally {
                ini_set('error_log', (string) $log);
            }
        }
        return self::$now;
    }

    /** Recursive compare: numbers within 1e-9 and of the same type, everything else identical. */
    private function assertSameShape($expected, $actual, string $path): void
    {
        if (self::deliberate($path) !== null) {
            if (json_encode($expected, JSON_PRESERVE_ZERO_FRACTION) !== json_encode($actual, JSON_PRESERVE_ZERO_FRACTION)) $this->changed[] = $path;
            return;
        }
        if (is_array($expected)) {
            $this->assertIsArray($actual, $path);
            $this->assertSame(array_keys($expected), array_keys($actual), "{$path}: keys");
            foreach ($expected as $k => $v) $this->assertSameShape($v, $actual[$k], "{$path}/{$k}");
            return;
        }
        if (is_int($expected) || is_float($expected)) {
            $this->assertSame(gettype($expected), gettype($actual), "{$path}: type");
            $this->assertEqualsWithDelta($expected, $actual, 1e-9, $path);
            return;
        }
        $this->assertSame($expected, $actual, $path);
    }

    public function testFixtureCoversThePresetsAndTheFallbackLabels(): void
    {
        $keys = array_keys(self::base());
        $this->assertSame(array_merge(self::PRESETS, ['(null)', "('')", 'stoic', 'Volatile']), $keys);
        // spot checks that the fixture is the old tables (MDD 1.3 / 15.4), not the engine
        $this->assertSame(0.6, self::base()['Guarded']['passion_mult']);
        $this->assertSame(1.0, self::base()['Humble']['resistance']['trust'], 'Humble has no MDD 15.4 row: 1.0 (Q6)');
        $this->assertSame(1.5, self::base()['Volatile']['resistance']['affinity'], 'the unreachable Volatile row');
        $this->assertSame(-1.5, self::base()['(null)']['bleedout'], 'postrequest default, not Stoic -0.5');
    }

    /** Every consumer, every label: today's value (design §6.2 RelDynTraitEquivalenceTest). */
    public function testEveryConsumerReadsTodaysValueThroughTheEngine(): void
    {
        $base = self::base();
        $now = self::now();
        $this->assertSame(array_keys($base), array_keys($now));
        foreach ($base as $label => $consumers) {
            $this->assertSame(array_keys($consumers), array_keys($now[$label]), "{$label}: consumers");
            foreach ($consumers as $consumer => $value) {
                $this->assertSameShape($value, $now[$label][$consumer], "{$label}/{$consumer}");
            }
        }
        $this->assertEveryDeliberatePatternIsReal(false);
    }

    /** Every deliberate change is real: each pattern (consumer or column) matches a changed path. */
    private function assertEveryDeliberatePatternIsReal(bool $columns): void
    {
        foreach (self::DELIBERATE as $fix => $patterns) {
            foreach ($patterns as $pat) {
                if (str_contains($pat, '/column/') !== $columns) continue;
                $hit = array_filter($this->changed, fn($p) => fnmatch($pat, $p, FNM_NOESCAPE));
                $this->assertNotEmpty($hit, "{$fix}: pattern {$pat} changes nothing (stale allow-list entry)");
            }
        }
    }

    /** Each registered column at each preset POINT (not the label) is the old table value. */
    public function testEveryColumnAtEveryPresetPointIsTheOldTableValue(): void
    {
        $base = self::base();
        $points = RelDynTraits::points();
        $this->assertSame(self::PRESETS, array_keys($points));
        foreach (self::PRESETS as $p) {
            $x = $points[$p];
            $b = $base[$p];
            $expect = [
                'passion_mult' => $b['passion_mult'], 'reunion_mult' => $b['reunion_mult'],   // bleedout: no longer a column (phase 3)
                'jealousy_mult' => $b['jealousy_mult'], 'tier_retention' => $b['tier_retention'], 'absence_decay' => $b['absence_decay'],
            ];
            foreach (RelationshipDynamics::TEMPERAMENT_BASELINES as $dim => $_) {
                $expect["baseline_{$dim}"] = $b['baseline'][$dim];
            }
            foreach (['affinity', 'passion', 'warmth', 'maturity', 'coord_m', 'coord_f', 'arousal', 'valence', 'trust', 'comfort', 'respect', 'self_confidence'] as $dim) {
                $expect["y_{$dim}_up"] = $b['plasticity'][$dim]['Y_up'];
                $expect["y_{$dim}_down"] = $b['plasticity'][$dim]['Y_down'];
            }
            foreach (['affinity', 'trust', 'comfort', 'respect'] as $sig) {   // maturity: retired (phase 3)
                $expect["resist_{$sig}"] = $b['resistance'][$sig];
            }
            // phase 3 (A16 split): the loss side is the MDD's Y_down column; Humble resists nothing (1.0)
            foreach (['trust', 'comfort'] as $sig) {
                $expect["resist_{$sig}_down"] = $p === 'Humble' ? 1.0 : $b['plasticity'][$sig]['Y_down'];
            }
            foreach (['half_life', 'decay_rate', 'lambda', 'passion_decay'] as $k) {
                $expect["warmth_{$k}"] = RelationshipDynamics::CURVE_PARAMS[$b['warmth_curve']][$k];
            }
            // A23 gates as the old code applied them: 'injured' moved trust, 'bloody' moved respect
            $expect['healer_gate'] = isset($b['physical']['injured']['injured']['trust']) ? 1.0 : 0.0;
            $expect['warrior_gate'] = isset($b['physical']['bloody']['bloody']['respect']) ? 1.0 : 0.0;
            foreach ($expect as $col => $v) {
                if (self::deliberate("{$p}/column/{$col}") !== null) {   // a phase-3 fix: its own test
                    if (abs($v - RelDynTraits::value($x, $col)) > 1e-9) $this->changed[] = "{$p}/column/{$col}";
                    continue;
                }
                // (types are the consumers' business: the consumer-level test checks them)
                $this->assertEqualsWithDelta($v, RelDynTraits::value($x, $col), 1e-9, "{$p} {$col}");
            }
            // every registered column is covered above except charisma (checked through the consumer)
            foreach (array_keys(RelDynTraits::columns()) as $col) {
                if (!str_starts_with($col, 'charisma_')) $this->assertArrayHasKey($col, $expect, "column {$col} is checked");
            }
            // label-valued surfaces: nearest preset of the point is the preset itself
            $this->assertSame(['name' => $p, 'distance' => 0.0], RelDynTraits::nearestPreset($x));
            $this->assertSame($b['maturity_type'], RelDynTraits::maturityCorner($x));
            // A17: the exact two-axis formula gives the corner's Y at the preset's (Rs, L)
            [$up, $down] = RelDynTraits::maturityY($x['Rs'], $x['L']);
            $corner = RelationshipDynamics::MATURITY_PLASTICITY_VALUES[$b['maturity_type']];
            $this->assertEqualsWithDelta($corner['Y_up'], $up, 1e-9, "{$p} A17 Y_up");
            $this->assertEqualsWithDelta($corner['Y_down'], $down, 1e-9, "{$p} A17 Y_down");
            // A8 / A14 identities and A9 maturity_start (design §3.1)
            $this->assertEqualsWithDelta($b['baseline']['warmth'], 100 * $x['W'], 1e-9, "{$p} W = warmth / 100");
            $this->assertEqualsWithDelta($b['baseline']['self_confidence'], 100 * $x['C'], 1e-9, "{$p} C = self-confidence / 100");
            $this->assertEqualsWithDelta($b['baseline']['maturity'], $x['maturity_start'], 1e-9, "{$p} maturity_start");
        }
        $this->assertEveryDeliberatePatternIsReal(true);
    }

    /** Design §3.3: rho <= d_min, so a preset's residual never reaches another preset. */
    public function testResidualReachStaysInsideTheClosestPresetPair(): void
    {
        $this->assertEqualsWithDelta(0.317, RelDynTraits::minPresetDistance(), 5e-4, 'Humble-Gentle');
        $this->assertLessThanOrEqual(RelDynTraits::minPresetDistance(), RelDynTraits::residualReach());
        $this->assertGreaterThan(0.0, RelDynTraits::residualReach());
        $pts = array_values(RelDynTraits::points());
        foreach ($pts as $i => $a) {
            foreach ($pts as $j => $b) {
                if ($i !== $j) $this->assertGreaterThanOrEqual(RelDynTraits::residualReach(), RelDynTraits::distance($a, $b));
            }
        }
    }

    /** Design §3.6: the two "no temperament" cases stay apart. */
    public function testNoVoteFallbackIsTheStoicPointAndNullStaysNull(): void
    {
        // 1. nothing voted: the NPC IS Stoic everywhere
        $profile = RelationshipDynamics::deriveNpcProfile('Nobody In Particular', []);
        $this->assertSame('Stoic', $profile['temperament']);
        $this->assertSame('fallback', $profile['sources']['temperament']);
        $this->assertSame(RelDynTraits::points()['Stoic'], RelDynTraits::vectorFor($profile['temperament']));
        // 2. inferred_temperament null: no vector, every consumer keeps its own default
        $this->assertNull(RelDynTraits::vectorFor(RelDynTraits::FROM_DYNAMICS, ['inferred_temperament' => null]));
        $this->assertNull(RelDynTraits::vectorFor('stoic'), 'exact names only, as the old tables were keyed');
        $null = self::base()['(null)'];
        $this->assertSame(1.0, $null['passion_mult']);
        $this->assertSame(-15, $null['tier_retention']);
        $this->assertSame('Adaptive', $null['maturity_type']);
        $this->assertSame('open_heart', $null['sensitivity_curve']);
        $this->assertSame('moderate', $null['warmth_curve']);
        $this->assertSame(RelationshipDynamics::LL_TIME, $null['love_language']);
        // the neutral consumers do not read Stoic for null (only the '?? Stoic' ones do, in their own code)
        $this->assertNotSame(self::base()['Stoic']['passion_mult'], $null['passion_mult']);
        $this->assertNotSame(self::base()['Stoic']['bleedout'], $null['bleedout']);
        $synced = RelDynTraits::syncStored(['inferred_temperament' => null, 'traits' => ['insecure']]);
        $this->assertNull($synced['trait_vector']);
        $this->assertSame(['insecure'], $synced['traits'], 'the trait TAG list is untouched');
    }

    /** Design §4.6: trait_vector (new key) mirrors the label's preset point; 'traits' stays the tags. */
    public function testStoredVectorMirrorsTheLabelAndTagsAreUntouched(): void
    {
        foreach (self::PRESETS as $p) {
            $d = RelDynTraits::syncStored(['inferred_temperament' => $p, 'traits' => ['egocentric']]);
            $this->assertSame(array_values(RelDynTraits::TRAITS), array_slice(array_keys($d['trait_vector']), 0, 10));
            $this->assertSame(RelDynTraits::points()[$p], RelDynTraits::fromStored($d['trait_vector']), $p);
            $this->assertSame(['source' => 'preset', 'preset' => $p, 'assignment' => 'label'], $d['_trait_vector_src']);
            $this->assertSame(['nearest' => $p, 'distance' => 0.0], $d['trait_preset']);
            $this->assertSame(RelDynTraits::VERSION, $d['trait_vector_version']);
            $this->assertSame(['egocentric'], $d['traits']);
            $this->assertEqualsWithDelta(RelationshipDynamics::TEMPERAMENT_BASELINES['maturity'][$p], $d['trait_vector']['maturity_start'], 1e-12);
        }
        // ensureTemperamentProfile (no core row, no DB): Stoic fallback resolved and stored with its vector
        $d = RelationshipDynamics::migrateDimensions(RelationshipDynamics::defaultDynamics());
        $this->assertTrue(RelationshipDynamics::ensureTemperamentProfile('Nobody In Particular', $d));
        $this->assertSame('Stoic', $d['inferred_temperament']);
        $this->assertSame(RelDynTraits::toStored(RelDynTraits::points()['Stoic']), $d['trait_vector']);
    }

    /** profile_overrides.trait_vector: accepted for later (phase 2), not read by the phase-1 assignment. */
    public function testTraitVectorOverrideIsStoredButDoesNotMoveAssignment(): void
    {
        $this->assertContains('trait_vector', RelationshipDynamics::PROFILE_OVERRIDE_FIELDS);
        $d = RelationshipDynamics::migrateDimensions(RelationshipDynamics::defaultDynamics());
        $this->assertTrue(RelationshipDynamics::setProfileOverride($d, 'temperament', 'Guarded'));
        $before = $d;
        $this->assertTrue(RelationshipDynamics::setProfileOverride($d, 'trait_vector', ['guard' => 0.4, 'Pd' => 0.9]));
        $this->assertSame(['guard' => 0.4, 'pride' => 0.9], $d['profile_overrides']['trait_vector']);
        $this->assertSame('Guarded', $d['inferred_temperament']);
        $this->assertSame($before['trait_vector'], $d['trait_vector'], 'phase 1: the vector is the label\'s preset point');
        $this->assertSame($before['dimensions'], $d['dimensions']);
        $this->assertSame($before['traits'], $d['traits']);
        $this->assertSame(0.6, RelDynTraits::param($d['inferred_temperament'], 'passion_mult', 1.0, $d));
        // invalid overrides change nothing
        foreach ([['guard' => 1.2], ['charm' => 0.5], [], 'Guarded', ['guard' => 'high']] as $bad) {
            $this->assertFalse(RelationshipDynamics::setProfileOverride($d, 'trait_vector', $bad), json_encode($bad));
        }
        $this->assertTrue(RelationshipDynamics::setProfileOverride($d, 'trait_vector', null));
        $this->assertArrayNotHasKey('trait_vector', $d['profile_overrides']);
    }

    /**
     * Setting or clearing profile_overrides.trait_vector must not re-run the profile resolution:
     * a stored temperament that is not an override (editor, Sharmat, an arc) stays, and so do a
     * hand-changed maturity type and trait tag list. Only the override field itself changes.
     */
    public function testTraitVectorOverrideLeavesAStoredNonOverrideProfileAlone(): void
    {
        $d = RelationshipDynamics::migrateDimensions(RelationshipDynamics::defaultDynamics());
        $d['inferred_temperament'] = 'Proud';   // stored by something else, not in profile_overrides
        RelationshipDynamics::ensureTemperamentProfile('Nobody In Particular', $d);
        $this->assertSame('Proud', $d['inferred_temperament']);
        $this->assertSame('Stoic', $d['_profile_autogen']['base_temperament']);
        $this->assertArrayNotHasKey('temperament', (array) ($d['profile_overrides'] ?? []));
        // dependents changed since the resolution, also by something else
        $d['dimensions']['maturity']['plasticity_type'] = 'Volatile';
        $d['traits'] = ['egocentric'];
        $d = RelDynTraits::syncStored($d);
        $before = $d;
        $this->assertSame(0.8, RelDynTraits::param($d['inferred_temperament'], 'passion_mult', 1.0, $d));

        $this->assertTrue(RelationshipDynamics::setProfileOverride($d, 'trait_vector', ['guard' => 0.4]));
        $this->assertSame(['guard' => 0.4], $d['profile_overrides']['trait_vector']);
        $expect = $before;
        $expect['profile_overrides'] = ['trait_vector' => ['guard' => 0.4]] + (array) ($before['profile_overrides'] ?? []);
        $this->assertSame($expect, $d, 'only profile_overrides.trait_vector changes');
        $this->assertSame(0.8, RelDynTraits::param($d['inferred_temperament'], 'passion_mult', 1.0, $d));

        $this->assertTrue(RelationshipDynamics::setProfileOverride($d, 'trait_vector', null));
        $this->assertSame((array) ($before['profile_overrides'] ?? []), $d['profile_overrides']);
        unset($d['profile_overrides'], $before['profile_overrides']);
        $this->assertSame($before, $d, 'clearing it changes nothing else');
    }

    /** Decisions §16.4: Ashe keeps the Guarded preset (and her Resilient maturity override). */
    public function testAsheKeepsTheGuardedPreset(): void
    {
        $profile = RelationshipDynamics::deriveNpcProfile('Ashe', []);
        $this->assertSame('Guarded', $profile['temperament']);
        $this->assertSame('preset', $profile['sources']['temperament']);
        $this->assertSame('Resilient', $profile['maturity_type']);
        $this->assertSame(RelDynTraits::points()['Guarded'], RelDynTraits::vectorFor($profile['temperament']));
        $this->assertSame(self::base()['Guarded']['baseline'], self::now()['Guarded']['baseline']);
    }

